23	    /// Detect return type annotations that are misleadingly wider than what
24	    /// the implementation actually returns.
25	    ///
26	    /// Reports when a function's explicit return type annotation is wider than
27	    /// what TypeScript would infer from the implementation, hiding precise types
28	    /// from callers.
29	    ///
30	    /// ## Examples
31	    ///
32	    /// ### Invalid
33	    ///
34	    /// ```ts,expect_diagnostic,file=invalid.ts
35	    /// function getStatus(b: boolean): string { if (b) return "loading"; return "idle"; }
36	    /// ```
